    { term: "Federal system", def: "A system of government in which power is shared between a central government and regional states." },
    { term: "National integration", def: "The process of uniting different groups into one nation with equal citizenship." },
    { term: "National identity", def: "The shared sense of belonging to one nation." },
    { term: "Fragmentation", def: "The breaking of a state or society into separate, disconnected parts." },
    { term: "Common citizenship", def: "The shared status and rights that all members of the nation enjoy equally." },
    { term: "Loyalty to the nation", def: "A citizen's faithful commitment to their country." }
